const clone = <T>(value: T): T => JSON.parse(JSON.stringify(value));
const previewId = () => globalThis.crypto?.randomUUID?.() ?? `preview-${Date.now()}-${Math.random().toString(16).slice(2)}`;

const createPreviewUser = (email = 'demo@zoot.local', fullName = 'Zoot Preview'): User => ({
  id: 'preview-user',
  aud: 'authenticated',
  role: 'authenticated',
  email,
  email_confirmed_at: new Date().toISOString(),
  phone: '',
  confirmed_at: new Date().toISOString(),
  last_sign_in_at: new Date().toISOString(),
  app_metadata: { provider: 'preview', providers: ['preview'] },
  user_metadata: { full_name: fullName },
  identities: [],
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString(),
  is_anonymous: false,
} as User);

const createPreviewSession = (email?: string, fullName?: string): Session => {
  const user = createPreviewUser(email, fullName);
  return {
    access_token: 'preview-access-token',
    refresh_token: 'preview-refresh-token',
    expires_in: 60 * 60 * 24,
    expires_at: Math.floor(Date.now() / 1000) + 60 * 60 * 24,
    token_type: 'bearer',
    user,
  } as Session;
};

const readPreviewSession = (): Session | null => {
  if (!authStorage) return null;
  const raw = authStorage.getItem(PREVIEW_SESSION_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as Session;
  } catch {
    authStorage.removeItem(PREVIEW_SESSION_KEY);
    return null;
  }
};

const writePreviewSession = (session: Session | null) => {
  if (!authStorage) return;
  if (session) authStorage.setItem(PREVIEW_SESSION_KEY, JSON.stringify(session));
  else authStorage.removeItem(PREVIEW_SESSION_KEY);
};

class PreviewQueryBuilder {
  private operation: 'select' | 'insert' | 'update' | 'delete' | 'upsert' = 'select';
  private payload: unknown = null;
  private countRequested = false;
  private headOnly = false;
  private singleRow = false;
  private maybeSingleRow = false;
  private maxRows: number | null = null;

  constructor(private readonly table: string) {}

  select(_columns?: string, options?: { count?: string; head?: boolean }) {
    this.countRequested = Boolean(options?.count);
    this.headOnly = Boolean(options?.head);
    return this;
  }

  insert(payload: unknown) {
    this.operation = 'insert';
    this.payload = payload;
    return this;
  }

  update(payload: unknown) {
    this.operation = 'update';
    this.payload = payload;
    return this;
  }

  upsert(payload: unknown) {
    this.operation = 'upsert';
    this.payload = payload;
    return this;
  }

  delete() {
    this.operation = 'delete';
    return this;
  }

  eq() { return this; }
  neq() { return this; }
  gt() { return this; }
  gte() { return this; }
  lt() { return this; }
  lte() { return this; }
  in() { return this; }
  contains() { return this; }
  order() { return this; }
  range() { return this; }

  limit(count: number) {
    this.maxRows = count;
    return this;
  }

  maybeSingle() {
    this.maybeSingleRow = true;
    return Promise.resolve(this.resolve());
  }

  single() {
    this.singleRow = true;
    return Promise.resolve(this.resolve());
  }

  then<TResult1 = QueryResult, TResult2 = never>(
    onfulfilled?: ((value: QueryResult) => TResult1 | PromiseLike<TResult1>) | null,
    onrejected?: ((reason: unknown) => TResult2 | PromiseLike<TResult2>) | null,
  ) {
    return Promise.resolve(this.resolve()).then(onfulfilled, onrejected);
  }

  private resolve(): QueryResult {
    let rows = this.resolveRows();

    if (this.operation === 'insert' || this.operation === 'upsert') {
      const incoming = Array.isArray(this.payload) ? this.payload : [this.payload ?? {}];
      rows = incoming.map((row) => ({ id: previewId(), created_at: new Date().toISOString(), ...(row as Record<string, unknown>) }));
    }

    if (this.operation === 'update') rows = Array.isArray(this.payload) ? this.payload : [{ ...(this.payload as Record<string, unknown>) }];
    if (this.operation === 'delete') rows = [];
    if (this.maxRows !== null) rows = rows.slice(0, this.maxRows);

    const count = this.countRequested || this.headOnly ? rows.length : null;
    const data = this.headOnly ? null : this.singleRow || this.maybeSingleRow ? (rows[0] ?? null) : rows;

    return { data, error: null, count, status: 200, statusText: 'OK' };
  }

  private resolveRows(): Record<string, unknown>[] {
    switch (this.table) {
      case 'zooters':
        return clone(previewZooters);
      case 'household_profiles':
        return [clone(previewHousehold)];
      case 'subscription_plans':
        return [
          {
            id: 'preview-care-plus-plan',
            name: 'Care+',
            cadence: 'monthly',
            hours_per_visit: 0,
            monthly_price: 99,
            savings_pct: 0,
            perks: ['Home Memory', 'Favourite Zooter', 'Priority support', '1.5x ZootCred'],
            popular: true,
          },
        ];
      case 'bookings':
        return [
          { id: 'preview-booking-last', user_id: 'preview-user', scheduled_at: new Date(Date.now() - 12 * 864e5).toISOString(), status: 'completed', service_type: 'residential' },
        ];
      case 'notifications':
        return clone(previewNotifications);
      case 'loyalty_points':
      case 'zootcred_ledger':
        return [{ id: 'preview-zootcred', user_id: 'preview-user', balance: 145, amount: 145, reason: 'Welcome preview credit', created_at: new Date().toISOString() }];
      case 'favorites':
      case 'property_accounts':
      case 'recurring_schedules':
      case 'support_tickets':
      case 'payment_records':
      case 'user_subscriptions':
      case 'admin_review_queue':
      case 'integration_outbox':
      case 'booking_status_events':
      case 'zooter_jobs':
      default:
        return [];
    }
  }
}

const createPreviewSupabaseClient = () => {
  const subscribers = new Set<AuthSubscriber>();
  const notify = (event: string, session: Session | null) => subscribers.forEach((callback) => callback(event, session));

  return {
    auth: {
      onAuthStateChange(callback: AuthSubscriber) {
        subscribers.add(callback);
        window.setTimeout(() => callback('INITIAL_SESSION', readPreviewSession()), 0);
        return { data: { subscription: { unsubscribe: () => subscribers.delete(callback) } } };
      },
      async getSession() {
        return { data: { session: readPreviewSession() }, error: null };
      },
      async signInWithPassword({ email }: { email: string; password: string }) {
        const session = createPreviewSession(email);
        writePreviewSession(session);
        notify('SIGNED_IN', session);
        return { data: { user: session.user, session }, error: null };
      },
      async signUp({ email, options }: { email: string; password: string; options?: { data?: { full_name?: string } } }) {
        const session = createPreviewSession(email, options?.data?.full_name);
        writePreviewSession(session);
        notify('SIGNED_IN', session);
        return { data: { user: session.user, session }, error: null };
      },
      async signOut() {
        writePreviewSession(null);
        notify('SIGNED_OUT', null);
        return { error: null };
      },
      async resetPasswordForEmail() {
        return { data: {}, error: null };
      },
      async updateUser() {
        const session = readPreviewSession() ?? createPreviewSession();
        writePreviewSession(session);
        notify('USER_UPDATED', session);
        return { data: { user: session.user }, error: null };
      },
      async signInWithOAuth() {
        return { data: { provider: null, url: null }, error: new Error('OAuth requires Supabase provider credentials.') };
      },
      async exchangeCodeForSession() {
        const session = readPreviewSession() ?? createPreviewSession();
        writePreviewSession(session);
        notify('SIGNED_IN', session);
        return { data: { session, user: session.user }, error: null };
      },
    },
    from(table: string) {
      return new PreviewQueryBuilder(table);
    },
    channel(name: string) {
      return {
        name,
        on() { return this; },
        subscribe() { return this; },
        unsubscribe() { return 'ok'; },
      };
    },
    removeChannel() {
      return Promise.resolve('ok');
    },
    rpc() {
      return Promise.resolve({ data: null, error: null });
    },
    functions: {
      async invoke(name: string, options?: { body?: Record<string, unknown> }) {
        const session = readPreviewSession() ?? createPreviewSession();
        writePreviewSession(session);

        if (name === 'create-booking-request') {
          return {
            data: {
              booking_ids: [previewId()],
              status: 'pending',
              preview: true,
              requested_service: options?.body?.serviceType ?? null,
            },
            error: null,
          };
        }

        if (name === 'care-plus-membership') {
          const action = options?.body?.action;
          return {
            data: {
              subscription_id: previewId(),
              subscription_status: action === 'cancel_membership' ? 'cancelled' : 'pending_payment',
              payment_record_id: action === 'cancel_membership' ? null : previewId(),
              preview: true,
            },
            error: null,
          };
        }

        if (name === 'ops-workflow') {
          return {
            data: {
              preview: true,
              queued: true,
              action: options?.body?.action ?? null,
              order_id: previewId(),
              payment_record_id: previewId(),
              call_session_id: previewId(),
              incident_id: previewId(),
              application_id: previewId(),
              job_id: previewId(),
              status: 'queued',
            },
            error: null,
          };
        }

        return { data: null, error: new Error(`Preview function ${name} is not implemented.`) };
      },
    },
  };
};

if (isPreviewSupabase) {
  console.info('Zoot preview mode is active. Configure VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY for live Supabase.');
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

export const supabase = (
  isSupabaseConfigured
    ? createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
        auth: {
          storage: authStorage,
          persistSession: true,
          autoRefreshToken: true,
          detectSessionInUrl: true,
          flowType: 'pkce',
        },
      })
    : createPreviewSupabaseClient()
) as ReturnType<typeof createClient<Database>>;
